def get_quiz(domain_id: str) -> List[QuizQuestion]:
    return [q for q in QUIZZES if q.domain_id==domain_id]

def get_all_quizzes_grouped():
    d=defaultdict(list)
    for q in QUIZZES:
        d[q.domain_id].append(q)
    return d
